```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Threading.Tasks;
using Xunit;
using OpenRA.Mods.Common;
using System.Threading;

namespace OpenRA.Mods.Common.Tests
{
    public class WebServicesTests
    {
        private readonly WebServices _webServices;
        private readonly HttpListener _listener;

        public WebServicesTests()
        {
            _webServices = new WebServices();
            _listener = new HttpListener();
            _listener.Prefixes.Add("http://localhost:5000/");
            _listener.Start();
        }

        [Fact]
        public async Task CheckModVersion_ShouldSetModVersionStatusToLatest()
        {
            // Arrange
            _listener.BeginGetContext(new AsyncCallback(HandleRequest), "latest");

            // Act
            _webServices.CheckModVersion();
            await Task.Delay(1000); // Wait for the async operation to complete

            // Assert
            Assert.Equal(ModVersionStatus.Latest, _webServices.ModVersionStatus);
        }

        [Fact]
        public async Task CheckModVersion_ShouldSetModVersionStatusToOutdated()
        {
            // Arrange
            _listener.BeginGetContext(new AsyncCallback(HandleRequest), "outdated");

            // Act
            _webServices.CheckModVersion();
            await Task.Delay(1000); // Wait for the async operation to complete

            // Assert
            Assert.Equal(ModVersionStatus.Outdated, _webServices.ModVersionStatus);
        }

        [Fact]
        public async Task CheckModVersion_ShouldSetModVersionStatusToUnknown()
        {
            // Arrange
            _listener.BeginGetContext(new AsyncCallback(HandleRequest), "unknown");

            // Act
            _webServices.CheckModVersion();
            await Task.Delay(1000); // Wait for the async operation to complete

            // Assert
            Assert.Equal(ModVersionStatus.Unknown, _webServices.ModVersionStatus);
        }

        [Fact]
        public async Task CheckModVersion_ShouldSetModVersionStatusToPlaytestAvailable()
        {
            // Arrange
            _listener.BeginGetContext(new AsyncCallback(HandleRequest), "playtest");

            // Act
            _webServices.CheckModVersion();
            await Task.Delay(1000); // Wait for the async operation to complete

            // Assert
            Assert.Equal(ModVersionStatus.PlaytestAvailable, _webServices.ModVersionStatus);
        }

        private void HandleRequest(IAsyncResult result)
        {
            var context = _listener.EndGetContext(result);
            var response = context.Response;
            var responseString = (string)result.AsyncState;
            var buffer = System.Text.Encoding.UTF8.GetBytes(responseString);
            response.ContentLength64 = buffer.Length;
            var output = response.OutputStream;
            output.Write(buffer, 0, buffer.Length);
            output.Close();
        }

        public void Dispose()
        {
            _listener.Stop();
        }
    }
}
